import { describe, it } from "vitest";

// Chosen error reading: the spec defines rejection only at the CLI (non-zero exit,
// error text on stderr). In the domain, runScenario rejects by throwing an Error.

describe("quote — catalogue and base premiums (newcomer: +10 % first insurance, +5 G fee)", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("plain sword -> base 100 -> premium 115 G");
  it.todo("plain amulet -> base 60 -> premium 71 G");
  it.todo("plain staff -> base 80 -> premium 93 G");
  it.todo("plain potion -> base 40 -> premium 49 G");
  it.todo("2 runes -> base 50 -> premium 60 G");
  it.todo("2 moonstones -> base 50 -> premium 60 G");
  it.todo("3 runes -> block base 60 -> premium 71 G");
  it.todo("4 runes -> no block, base 100 -> premium 115 G");
  it.todo("7 runes -> base 175 -> 197.5 rounded up in MHPCO's favor -> premium 198 G");
  it.todo("2 runes + 1 moonstone -> no block (different types), base 75 -> 87.5 -> premium 88 G");
  it.todo("3 runes + 3 moonstones -> two blocks, base 120 -> premium 137 G");
  it.todo("quote with unknown item type 'broomstick' -> throws an Error");
});

describe("quote — item-specific modifiers", () => {
  it.todo("cursed steel sword, enchantment 3, newcomer -> premium 165 G");
  it.todo("sword enchantment 4, not cursed -> no high-enchantment surcharge -> premium 115 G");
  it.todo("sword enchantment 4, cursed -> curse only -> premium 165 G");
  it.todo("sword exactly enchantment 5, not cursed -> +30 % -> premium 145 G");
  it.todo("sword exactly enchantment 5, cursed -> both surcharges -> premium 195 G");
  it.todo("cursed sword + plain amulet -> base 160 + 50 curse (sword only) + 16 first insurance + 5 -> premium 231 G");
});

describe("quote — policy-wide modifiers and customer history", () => {
  it.todo("customer exactly 2 years, plain sword -> loyalty applies -> premium 95 G");
  it.todo("customer 1 year, plain sword -> no loyalty -> premium 115 G");
  it.todo("newcomer second quote, plain sword -> follow-up -15 %, first insurance still +10 % -> premium 100 G");
  it.todo("newcomer third quote, plain sword -> follow-up discount again -> premium 100 G");
  it.todo("3-year customer second quote, cursed steel sword enchantment 7 -> premium 160 G");
});

describe("claim — reimbursement clauses", () => {
  it.todo("steel sword enchantment 3, damage 500 -> payout 400, remainingCap 1600");
  it.todo("rune, damage 200 -> payout 100, remainingCap 400");
  it.todo("steel sword enchantment 9, damage 1000 -> 50 % then deductible -> payout 400, remainingCap 1600");
  it.todo("dragon sword enchantment 5, damage 800 -> full then deductible -> payout 700, remainingCap 1300");
  it.todo("dragon sword exactly enchantment 8, damage 1000 -> 50 % wins -> payout 400");
  it.todo("dragon sword enchantment 9, damage 1000 -> 50 % wins -> payout 400");
  it.todo("amulet enchantment 9, damage 901 -> 350.5 rounded down -> payout 350");
});

describe("claim — deductible per damaged item", () => {
  it.todo("sword (500) and amulet (300) damaged by a dragon -> payout 600, remainingCap 2600");
  it.todo("two insured swords both damaged 500 -> payout 800, remainingCap 3200 (cap 4000)");
});

describe("claim — cap", () => {
  it.todo("cursed sword: cap from unmodified value 2000; damage 1500 -> payout 1400, remainingCap 600");
  it.todo("sword + 3 runes: insurance sum 1750, cap 3500; sword damage 3000 -> payout 2900, remainingCap 600");
  it.todo("sword + amulet: cap 3200; damages 3000 + 500 -> desired 3300 limited -> payout 3200, remainingCap 0");
  it.todo("two successive claims of 1500 on one sword -> 1400/600 then 600/0");
  it.todo("claim refers to its policy by quote step index -> amulet policy at step 1, damage 300 -> payout 200, remainingCap 1000");
});

describe("claim — rejections", () => {
  it.todo("damage to an amulet when only a sword is insured -> throws an Error");
  it.todo("damage to an unknown item type -> throws an Error");
  it.todo("two sword damages but only one sword insured -> throws an Error");
  it.todo("damage amount -200 -> throws an Error");
});

