input.command:
cat > src/claim-office.ts <<'EOF'
export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type Result = { premium: number } | { payout: number; remainingCap: number };

export function runScenario(scenario: Scenario): { results: Result[] } {
  return { results: scenario.steps.map(() => ({ premium: 0 })) };
}
EOF
pnpm test 2>&1 | grep -E "FAIL|Assertion|expected|Test Files|Tests" | head; npx tsc --noEmit && echo TSC OK

