const FIRST_INSURANCE_SURCHARGE = 0.1;

function quote(items: Item[]): number {
  const basePremium = items.length * SWORD_BASE_PREMIUM;
  return basePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): { results: Result[] } {
  return {
    results: scenario.steps.map((step) => ({ premium: quote((step as QuoteStep).items) })),
  };
}''')
open(p,'w').write(s)
EOF
pnpm test 2>&1 | grep -E "AssertionError|Test Files|Tests "; npx tsc --noEmit && echo TSC OK

