export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type Result = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;

function quote(items: Item[]): number {
  const basePremium = policyBasePremium(items);
  return (basePremium * (PERCENT + FIRST_INSURANCE_SURCHARGE_PERCENT)) / PERCENT + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): { results: Result[] } {
  return {
    results: scenario.steps.map((step) => ({ premium: quote((step as QuoteStep).items) })),
  };
}
